-- Rifts World Book 26: Dinosaur Swamp, the eight vehicles (printed 101-106)
-- 8 vehicle rows, with 21 locations and 3 weapon entries.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~250-dinosaur-swamp-vehicles.sql
--
-- Written by scripts/vessel-sql.mjs from 1 worker file(s). Every value
-- is printable ASCII, every row cites its book, and a Main Body location
-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('copperhead-emg-2098-bicycle', 'Copperhead EMG-2098 Electric Motor Geared Bicycle', 'rifts', 'vehicle', 'One rider', 'One, uncomfortably', 'Pedalling 20 mph (32 km) in short spurts, 8-10 mph (13-16 km) sustainable; 25 mph (40 km) on the electric motor', NULL, NULL, 'Seat height 3 ft (0.9 m); width 1 ft 6 in (0.45 m) at the handlebar; length 5 ft (1.5 m); weight 45 lbs (20 kg). May vary by 20% between models.', '0.0225', 30, 1, NULL, 9000, 'Market Cost: 9,000-12,000 credits.', 'Model Type: EMG-2098. Class: electric bicycle. Manufacturer: generic, Black Market. M.D. composite frame, puncture-proof tires, small solar panels that charge the battery, onboard computer (compass, tachometer, clock, power gauge), head and rear lights. Range 160 miles (256 km) per full recharge (6 hours), triple that on an E-Clip (96 hours per clip). Cargo: limited, 600 lbs (270 kg) as printed. Power: manual and electric motor. No weapons.', 'Rifts World Book 26: Dinosaur Swamp p.102'),
  ('old-mule-twd-1138-bicycle', 'Old Mule TWD-1138 Two Wheeled, Gear Driven Bicycle', 'rifts', 'vehicle', 'One rider', NULL, '20 mph (32 km); 10-15 mph (16-24 km) sustained', 'Not possible', NULL, 'Seat height 3 ft (0.9 m); width 1 ft 4 in (0.4 m) at the handlebar; length 4 ft 8 in (1.4 m); weight 25 lbs (11.25 kg).', '0.0125', 40, 1, NULL, 7000, 'Market Cost: 7,000-10,000 credits.', 'Model Type: TWD-1138. Class: manual bicycle. Manufacturers: Black Market, Northern Gun, Manistique Imperium; the Coalition builds an identical model, the CS-015 Bicycle, for CS Rangers and ''Burbs patrols. Dual chain drive for two-wheel drive, removable magneto-powered lights, folds in half, comes with a carry backpack. Range effectively unlimited: an average soldier covers about 75-150 miles (120-240 km) on a good day. Cargo: what the rider carries. No weapons.', 'Rifts World Book 26: Dinosaur Swamp p.102'),
  ('wildcat-orm-108-dirt-bike', 'Wildcat ORM-108 Off-Road Dirt Bike', 'rifts', 'vehicle', 'One rider', NULL, '100 mph (160 km), even in rugged conditions; +10% to tricks, stunts and maneuvers over 30 mph (48 km) in rough terrain', 'Not possible', NULL, 'Seat height 3 ft 3 in (0.97 m); width 1 ft 8 in (0.5 m) at the handlebar; length 4 ft 8 in (1.46 m); weight 220 lbs (99 kg).', '0.11', 45, 1, NULL, 20000, 'Market Cost: 20,000-30,000 credits combustion, 30,000-40,000 electric; the higher price buys the maximum M.D.C.', 'Model Type: ORM-108. Class: motorcycle. Manufacturers: Black Market, Northern Gun and most major manufacturers. A rugged dirt bike with heavy shocks, smooth off-road and weaker on the highway than the Highway-Man. Range 300 miles (480 km) electric, 500 miles (800 km) combustion. Main Body 45 to 75 M.D.C. by price (the low end stored). Cargo: what the rider carries. No weapons.', 'Rifts World Book 26: Dinosaur Swamp p.102-103'),
  ('king-grizzly-kg-atv4', 'King Grizzly KG-ATV4 4-Wheel ATV', 'rifts', 'vehicle', 'One rider', 'One, not very comfortably', '60 mph (96 km) maximum; 35-45 mph (56-72 km) likely over rugged terrain; climbs 20 degree inclines in low gear', 'Not possible', NULL, 'Seat height 2 ft 10 in (0.88 m); width 3 ft 8 in (1.1 m); length 4 ft 3 in (1.3 m); weight 600 lbs (270 kg).', '0.3', 95, 1, NULL, 23000, 'Market Cost: 23,000 credits combustion, 28,000 electric; a nuclear engine adds 2 million.', 'Model Type: KG-ATV4. Class: 4-wheel all-terrain vehicle. Manufacturers: Black Market, Northern Gun and most major manufacturers; the CS produces a similar version, the CS-Mark III ATV. Good in deep snow. Range 300 miles (480 km) electric, 400 miles (640 km) combustion, unlimited (15 year life) nuclear. Cargo: three watertight boxes, 300 lbs (135 kg) in all; towing 2000 lbs (900 kg). Weapons: none standard; one or two light weapons fixed forward can be added for 15,000-30,000 credits.', 'Rifts World Book 26: Dinosaur Swamp p.103-104'),
  ('marsh-raptor-mr-atv-buggy', 'Marsh Raptor MR-ATV All-Terrain Buggy', 'rifts', 'vehicle', 'One driver', 'One comfortably; a second by giving up half the cargo space', '200 mph (320 km) over sand, marsh and level ground; halved over rocky ground and woodland', 'Not possible', NULL, 'Height 5 ft 9 in (1.75 m); width 5 ft 2 in (1.57 m); length 9 ft 3 in (2.8 m); weight 1125 lbs (506 kg).', '0.5625', 65, 1, NULL, 22000, 'Market Cost: 22,000 credits combustion, 28,000 electric; a nuclear engine adds 2 million. Comes with the light machine-gun or the grenade launcher.', 'Model Type: MR-ATV. Class: 4-wheel all-terrain vehicle. Manufacturers: Black Market, Northern Gun and most major manufacturers. A fast recon buggy favoured by Char gangs, pirates, marsh raiders and scouts; poor on highways, in woods and mountains. Range 400 miles (640 km) electric, 600 miles (960 km) combustion, unlimited (15 year life) nuclear. Cargo: open area 4x2x2 ft behind the seats; over 250 lbs (112 kg) hurts performance. Mounts a light machine-gun or an automatic grenade launcher on the front, usable by driver or passenger.', 'Rifts World Book 26: Dinosaur Swamp p.104'),
  ('prowler-guw-p002-water-craft', 'Prowler GUW-P002 General Utility Water Craft', 'rifts', 'ship', 'One pilot, plus up to 4 crewmen', 'Up to 30 human-sized (45 cramped) with no other cargo', NULL, NULL, '80 mph (128 km) maximum; cruising 20-30 mph (32-48 km)', 'Height 10 ft (3 m), inside depth 2 ft 3 in (0.64 m); width 9 ft (2.7 m); length 25-30 ft (7.6-9.1 m); weight 2640-3200 lbs (1188-1440 kg).', '1.32', 145, 1, NULL, 120000, 'Market Cost: 120,000-150,000 credits; a nuclear power supply adds 2 million.', 'Model Type: GUW-P002. Class: patrol boat. Manufacturers: Black Market, Northern Gun and most major manufacturers. A freshwater utility boat for fishing, cargo, housing, assault and smuggling, with an armored pilot station mid-boat; no open-ocean navigation gear, but can island-hop. Range 500 miles (800 km) combustion, unlimited (15 year life) nuclear. Cargo: four tons (8000 lbs). Power: combustion (nuclear is practically unheard of).', 'Rifts World Book 26: Dinosaur Swamp p.104-105'),
  ('skeeter-flat-bottomed-air-boat', 'Skeeter Flat-Bottomed Air Boat', 'rifts', 'ship', 'One pilot', 'Up to 2', NULL, NULL, '50 mph (80 km); cruising 20-30 mph (32-48 km)', 'Height 7 ft 4 in (2.2 m) with the propeller cowling; width 4 ft 6 in (1.4 m); length 10 ft 4 in (3.1 m); weight 350 lbs (157.5 kg).', '0.175', 65, 1, NULL, 11000, 'Market Cost: 11,000 credits combustion, 15,000 electric.', 'No model designation. Class: flat-bottom boat. Manufacturers: Black Market, Titan Industries and a couple of east-coast places. Often bought as a kit; one to three seats and a rear fan engine, for shallow marsh and everglades; a cheaper alternative to a hovercraft. Range 150 miles (240 km) per tank or charge. Cargo: up to 350 lbs (157.5 kg) including passengers. No weapons.', 'Rifts World Book 26: Dinosaur Swamp p.105'),
  ('tidal-shark-pb-004-power-board', 'Tidal Shark PB-004 Power Board', 'rifts', 'vehicle', 'One pilot', NULL, NULL, NULL, '40 mph (64 km)', 'Height 8 in (0.20 m); width 2 ft (0.60 m) at the widest point; length 8 ft 4 in (2.54 m); weight 115 lbs (51.7 kg).', '0.0575', 20, 1, NULL, 26000, 'Market Cost: 26,000 credits combustion, 40,000 electric. The Techno-Wizard version costs 180,000.', 'Model Type: PB-004. Class: surface water sled. Manufacturers: Black Market, Titan Industries and a couple of east-coast places; the Coalition has shown interest but builds none. A jet-powered surfboard steered by leaning, with a one-handed throttle on a tether cable. Range 100 miles (160 km). Cargo: none, pilot only. A Techno-Wizard version adds a mechanism that lets 10 P.P.E. power it for 10 minutes at 60 mph (96 km), 80 mph (128 km) along ley lines, and indefinitely along aquatic ley lines. No weapons.', 'Rifts World Book 26: Dinosaur Swamp p.105-106');

