INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('marsh-raptor-mr-atv-buggy', 1, '.40 Caliber Light Machine-Gun', '1D4 M.D. per 20 round burst; 1D4x10 S.D.C. per single shot', 1, '2000 ft (610 m)', 'Each burst is one melee attack of the shooter', '1200 round belt (60 bursts)', NULL, 'Belt-fed, armor-piercing, tripod on the dash or rear of the pilot compartment. Fitted instead of the grenade launcher. May be swapped for a light laser (2D6 M.D., 2000 ft, E-Clip of 20 shots or nuclear power) for 20,000 credits more.'),
  ('marsh-raptor-mr-atv-buggy', 2, 'Automatic Grenade Launcher', '4D6 M.D. to a 12 ft (3.6 m) blast area', 1, '1600 ft (488 m)', 'Single shot only; each shot is one melee attack of the shooter', '40 round belt', NULL, 'Belt-fed, tripod on the dash or rear. Fitted instead of the machine-gun.'),
  ('prowler-guw-p002-water-craft', 1, '14.7 mm Heavy Machine-Gun', '2D6 M.D. per 20 round burst; 4D6x10 S.D.C. per single shot', 1, '3000 ft (914 m)', 'Standard', '1000 round belt (50 bursts)', NULL, 'Belt-fed, armor-piercing, in an armored compartment at the bow. May be replaced by a light laser (2D6 M.D., 2000 ft, E-Clip of 20 shots) for 20,000 credits or a medium laser (3D6 M.D., 2000 ft, E-Clip of 12 shots) for 30,000; a twin-barreled laser doubles cost and damage.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 8 machines are in' AS assertion, count(*) AS got, 8 AS want
  FROM vehicles WHERE slug IN ('copperhead-emg-2098-bicycle', 'old-mule-twd-1138-bicycle', 'wildcat-orm-108-dirt-bike', 'king-grizzly-kg-atv4', 'marsh-raptor-mr-atv-buggy', 'prowler-guw-p002-water-craft', 'skeeter-flat-bottomed-air-boat', 'tidal-shark-pb-004-power-board');
SELECT 'their 21 locations are in' AS assertion, count(*) AS got, 21 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('copperhead-emg-2098-bicycle', 'old-mule-twd-1138-bicycle', 'wildcat-orm-108-dirt-bike', 'king-grizzly-kg-atv4', 'marsh-raptor-mr-atv-buggy', 'prowler-guw-p002-water-craft', 'skeeter-flat-bottomed-air-boat', 'tidal-shark-pb-004-power-board');
SELECT 'their 3 weapon entries are in' AS assertion, count(*) AS got, 3 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('copperhead-emg-2098-bicycle', 'old-mule-twd-1138-bicycle', 'wildcat-orm-108-dirt-bike', 'king-grizzly-kg-atv4', 'marsh-raptor-mr-atv-buggy', 'prowler-guw-p002-water-craft', 'skeeter-flat-bottomed-air-boat', 'tidal-shark-pb-004-power-board');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('copperhead-emg-2098-bicycle', 'old-mule-twd-1138-bicycle', 'wildcat-orm-108-dirt-bike', 'king-grizzly-kg-atv4', 'marsh-raptor-mr-atv-buggy', 'prowler-guw-p002-water-craft', 'skeeter-flat-bottomed-air-boat', 'tidal-shark-pb-004-power-board') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

